// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Changes: module, agent tool and text diffs"
// Changes: get_draft_changes – what adopting a draft would do to its project's current parts, as the changes module
//          computes it (the same output the human's Changes view renders), with the draft's base for the
//          "changed on both sides" flags. Read-only; works for open and ended drafts.

import { draftChanges } from '#/lib/changes'
import { readParts } from '#/lib/parts'
import { z } from 'zod'
import { draftOf, draftRef, projectOf } from './targets.server'
import { READ_ONLY, defineTool } from './tools.server'

export const getDraftChanges = defineTool({
  name: 'get_draft_changes',
  description:
    "Gets a draft's changes: what adopting it would do to its project as the project is now (not to the draft's " +
    'base), in the shape the human sees. Per part (definition, grammarRules, precTable, reductionRules): changed ' +
    '(draft part ≠ current project part) and changedOnBothSides (the project also changed that part since the draft ' +
    'was created – the human adopts such parts only on purpose). definition: line diffs of nonterminals, terminals ' +
    'and start; grammarRules / reductionRules: lines [{kind (same, added, removed), text, oldLine, newLine}]; ' +
    'precTable: addedTerminals, removedTerminals, cells [{stack, input, old, new}] ("" = empty cell). Derived from ' +
    'the definition and grammar rules: llTable {cells [{nonterminal, terminal, old, new}] with rules as {rule, text}, ' +
    'newConflicts, resolvedConflicts} and sets {nonterminals (Empty, First, Follow), predict (per rule number)} listing ' +
    'only changed entries (old/new null = missing on that side). Returns {target (the draft), project {id, revision}, changes}.',
  input: { draft: z.string().describe('Draft id (from create_draft or list_drafts)') },
  annotations: READ_ONLY,
  run: ({ draft: id }, { store }) => {
    const draft = draftOf(store, id)
    const project = projectOf(store, draft.projectId)
    return {
      target: draftRef(draft),
      project: { id: project.id, revision: project.revision },
      changes: draftChanges({ draft: draft.parts, project: readParts(project.data), base: draft.base.parts }),
    }
  },
})
